import fs from "node:fs";
import path from "node:path";
import matter from "gray-matter";

/** Checked in so typecheck can resolve it. Regenerated by next.config.ts. */
export const STYLE_GUIDE_INDEX_PATH = path.join(
  process.cwd(),
  "src/lib/guides/style-guide-index.generated.ts",
);

/** Slim guide card for style detail pages — no markdown body. */
export type StyleGuideCardData = {
  readonly slug: string;
  readonly title: string;
  readonly description: string;
  /** Guide category slug from frontmatter (string — keep next.config free of @ aliases). */
  readonly category: string;
  readonly imageUrl: string;
  readonly imageAlt: string;
  readonly imageWidth: number;
  readonly imageHeight: number;
  readonly hasRealImage: boolean;
  readonly tags: readonly string[];
};

const GUIDE_CATEGORY_SLUGS = new Set([
  "festivals",
  "couples-family",
  "trends",
  "seasonal",
  "occasions",
  "professional",
  "styles",
]);

export type StyleGuideIndexData = {
  readonly guides: Readonly<Record<string, StyleGuideCardData>>;
  /** styleId → published guide slugs that link to `/styles/{id}`. */
  readonly membership: Readonly<Record<string, readonly string[]>>;
};

const STYLE_HREF = /\]\(\/styles\/([a-z0-9]+(?:-[a-z0-9]+)*)\)/g;

const DEFAULT_CARD_WIDTH = 1200;
const DEFAULT_CARD_HEIGHT = 630;

/**
 * Explicit `/styles/{slug}` links in a published guide body.
 * Title auto-linking in prepareGuideMarkdown is not required — writers already
 * add Customize-this-prompt links for featured styles.
 */
export function extractStyleIdsFromGuideBody(body: string): string[] {
  const ids = new Set<string>();
  for (const match of body.matchAll(STYLE_HREF)) {
    const id = match[1];
    if (id) ids.add(id);
  }
  return [...ids].sort((a, b) => a.localeCompare(b));
}

function oneLineDescription(value: string): string {
  const trimmed = value.replace(/\s+/g, " ").trim();
  if (trimmed.length <= 140) return trimmed;
  const slice = trimmed.slice(0, 137);
  const boundary = slice.lastIndexOf(" ");
  return `${(boundary > 40 ? slice.slice(0, boundary) : slice).trimEnd()}…`;
}

function parseGuideCard(
  fileName: string,
  data: Record<string, unknown>,
  body: string,
): StyleGuideCardData | null {
  if (!fileName.endsWith(".mdx")) return null;
  const slug = fileName.slice(0, -".mdx".length);
  if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)) {
    throw new Error(`${fileName}: slug must be lowercase words separated by hyphens`);
  }
  if (data.draft !== false) return null;

  const title =
    typeof data.title === "string" && data.title.trim()
      ? data.title.trim()
      : slug;
  const description =
    typeof data.description === "string" && data.description.trim()
      ? oneLineDescription(data.description)
      : "";
  const category =
    typeof data.category === "string" && GUIDE_CATEGORY_SLUGS.has(data.category)
      ? data.category
      : typeof data.category === "string" && data.category.trim()
        ? data.category.trim()
        : "styles";

  const tags = Array.isArray(data.tags)
    ? data.tags.filter((t): t is string => typeof t === "string" && t.trim() !== "")
    : [];

  const og =
    data.ogImage && typeof data.ogImage === "object" && !Array.isArray(data.ogImage)
      ? (data.ogImage as Record<string, unknown>)
      : null;
  const hero =
    data.heroImage && typeof data.heroImage === "object" && !Array.isArray(data.heroImage)
      ? (data.heroImage as Record<string, unknown>)
      : null;

  const imageSource = hero ?? og;
  if (
    imageSource &&
    typeof imageSource.url === "string" &&
    imageSource.url.trim() &&
    typeof imageSource.alt === "string"
  ) {
    const width =
      typeof imageSource.width === "number" && imageSource.width > 0
        ? imageSource.width
        : typeof og?.width === "number" && og.width > 0
          ? og.width
          : DEFAULT_CARD_WIDTH;
    const height =
      typeof imageSource.height === "number" && imageSource.height > 0
        ? imageSource.height
        : typeof og?.height === "number" && og.height > 0
          ? og.height
          : DEFAULT_CARD_HEIGHT;
    return {
      slug,
      title,
      description,
      category,
      imageUrl: imageSource.url.trim(),
      imageAlt: imageSource.alt.trim() || title,
      imageWidth: width,
      imageHeight: height,
      hasRealImage: true,
      tags,
    };
  }

  // Prefer first real markdown image as a last resort for card art.
  const outsideFences = body
    .split(/(```[\s\S]*?```)/g)
    .filter((_, index) => index % 2 === 0)
    .join("\n");
  const imageMatch = /!\[([^\]]*)\]\(([^)\s]+)(?:\s+"[^"]*")?\)/.exec(outsideFences);
  if (imageMatch?.[2] && imageMatch[2] !== "guide-image-placeholder") {
    return {
      slug,
      title,
      description,
      category,
      imageUrl: imageMatch[2],
      imageAlt: (imageMatch[1] || title).trim(),
      imageWidth: DEFAULT_CARD_WIDTH,
      imageHeight: DEFAULT_CARD_HEIGHT,
      hasRealImage: true,
      tags,
    };
  }

  return {
    slug,
    title,
    description,
    category,
    imageUrl: "/opengraph-image",
    imageAlt: title,
    imageWidth: DEFAULT_CARD_WIDTH,
    imageHeight: DEFAULT_CARD_HEIGHT,
    hasRealImage: false,
    tags,
  };
}

/** Read published guides + style membership from content/guides (frontmatter + body). */
export function readStyleGuideIndex(
  dir = path.join(process.cwd(), "content", "guides"),
): StyleGuideIndexData {
  if (!fs.existsSync(dir)) {
    return { guides: {}, membership: {} };
  }

  const guides: Record<string, StyleGuideCardData> = {};
  const membershipLists = new Map<string, string[]>();

  for (const file of fs.readdirSync(dir)) {
    if (!file.endsWith(".mdx")) continue;
    const raw = fs.readFileSync(path.join(dir, file), "utf8");
    const parsed = matter(raw);
    const card = parseGuideCard(file, parsed.data as Record<string, unknown>, parsed.content);
    if (!card) continue;
    guides[card.slug] = card;
    for (const styleId of extractStyleIdsFromGuideBody(parsed.content)) {
      const list = membershipLists.get(styleId) ?? [];
      if (!list.includes(card.slug)) list.push(card.slug);
      membershipLists.set(styleId, list);
    }
  }

  const membership: Record<string, readonly string[]> = {};
  for (const [styleId, slugs] of [...membershipLists.entries()].sort((a, b) =>
    a[0].localeCompare(b[0]),
  )) {
    membership[styleId] = slugs.slice().sort((a, b) => a.localeCompare(b));
  }

  return { guides, membership };
}

function renderStringArray(values: readonly string[]): string {
  if (values.length === 0) return "[]";
  return `[\n${values.map((value) => `    ${JSON.stringify(value)},`).join("\n")}\n  ]`;
}

function renderTags(tags: readonly string[]): string {
  if (tags.length === 0) return "[]";
  return `[${tags.map((tag) => JSON.stringify(tag)).join(", ")}]`;
}

export function renderStyleGuideIndex(data: StyleGuideIndexData): string {
  const guideEntries = Object.keys(data.guides)
    .sort((a, b) => a.localeCompare(b))
    .map((slug) => {
      const g = data.guides[slug]!;
      return `  ${JSON.stringify(slug)}: {
    slug: ${JSON.stringify(g.slug)},
    title: ${JSON.stringify(g.title)},
    description: ${JSON.stringify(g.description)},
    category: ${JSON.stringify(g.category)},
    imageUrl: ${JSON.stringify(g.imageUrl)},
    imageAlt: ${JSON.stringify(g.imageAlt)},
    imageWidth: ${g.imageWidth},
    imageHeight: ${g.imageHeight},
    hasRealImage: ${g.hasRealImage},
    tags: ${renderTags(g.tags)},
  },`;
    })
    .join("\n");

  const membershipEntries = Object.keys(data.membership)
    .sort((a, b) => a.localeCompare(b))
    .map((styleId) => {
      const slugs = data.membership[styleId] ?? [];
      return `  ${JSON.stringify(styleId)}: ${renderStringArray(slugs)},`;
    })
    .join("\n");

  return `// Generated from content/guides by next.config.ts. Do not edit.
import type { StyleGuideCardData } from "./style-guide-index";

export const STYLE_GUIDE_CARDS: Readonly<Record<string, StyleGuideCardData>> = {
${guideEntries}
};

export const STYLE_GUIDE_MEMBERSHIP: Readonly<Record<string, readonly string[]>> = {
${membershipEntries}
};
`;
}

/** Writes the style↔guide index when content changes. */
export function writeStyleGuideIndex(
  dir = path.join(process.cwd(), "content", "guides"),
): StyleGuideIndexData {
  const data = readStyleGuideIndex(dir);
  const next = renderStyleGuideIndex(data);
  const current = fs.existsSync(STYLE_GUIDE_INDEX_PATH)
    ? fs.readFileSync(STYLE_GUIDE_INDEX_PATH, "utf8")
    : "";
  if (current !== next) fs.writeFileSync(STYLE_GUIDE_INDEX_PATH, next);
  return data;
}
